.player {
  width: 300px;
  margin: 24px;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.player p {
  margin: 0;
}

.ctrl {
  border: 0;
  background-color: transparent;
  font: inherit;
}

/* ---- Solution ---- */
.player {
  border-radius: 20px;
  background-color: #18181b;
  color: #ffffff;
}

.art {
  position: relative;
  height: 260px;
  border-radius: 14px;
  background-image:
    radial-gradient(circle at 30% 30%, #f472b6, transparent 50%),
    radial-gradient(circle at 70% 70%, #818cf8, transparent 50%),
    linear-gradient(135deg, #f97316, #7c3aed);
}

.art-label {
  position: absolute;
  right: 12px;
  bottom: 12px;
  left: 12px;
  padding: 10px 12px;
  border-radius: 10px;
  background-color: rgb(255 255 255 / 0.2);
  backdrop-filter: blur(10px);
  font-weight: 800;
  letter-spacing: 0.3em;
}

.info {
  margin-top: 16px;
}

.track {
  overflow: hidden;
  font-size: 16px;
  font-weight: 600;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.artist {
  color: #a1a1aa;
  font-size: 13px;
}

.progress {
  height: 4px;
  margin-top: 16px;
  overflow: hidden;
  border-radius: 999px;
  background-color: #3f3f46;
}

.fill {
  width: 36%;
  height: 100%;
  background-color: #f97316;
}

.times {
  display: flex;
  justify-content: space-between;
  margin-top: 6px;
  color: #a1a1aa;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 24px;
  margin-top: 12px;
}

.ctrl {
  color: #e4e4e7;
}

.play {
  position: relative;
  width: 56px;
  height: 56px;
  border: 0;
  border-radius: 50%;
  background-color: #f97316;
  box-shadow: 0 6px 16px rgb(249 115 22 / 0.45);
}

.play::before {
  content: "";
  position: absolute;
  top: 19px;
  left: 22px;
  width: 16px;
  height: 18px;
  background-color: #ffffff;
  clip-path: polygon(0 0, 100% 50%, 0 100%);
}
